  __nv_bfloat16* p_out = static_cast<__nv_bfloat16*>(arg_out.data_ptr());
  CUtensorMap p_out_tma = EncodeTma_out_tma(arg_out_tma);
  __nv_bfloat16* p_final_state = static_cast<__nv_bfloat16*>(arg_final_state.data_ptr());
  uint64_t v_state_indices_addr = (uint64_t)arg_state_indices_addr;
  int64_t v_state_slot_stride = (int64_t)arg_state_slot_stride;
  int32_t v_use_state_indices = (int32_t)arg_use_state_indices;
  float* p_initial_state_f32 = static_cast<float*>(arg_initial_state_f32.data_ptr());
  float* p_final_state_f32 = static_cast<float*>(arg_final_state_f32.data_ptr());
  int32_t v_uniform_seq_len = (int32_t)arg_uniform_seq_len;
  int32_t v_persistent_tasks = (int32_t)arg_persistent_tasks;
  int32_t v_persistent_stride = (int32_t)arg_persistent_stride;
  int32_t v_num_heads = (int32_t)arg_num_heads;
  int32_t v_use_initial_state = (int32_t)arg_use_initial_state;
  int32_t v_store_final_state = (int32_t)arg_store_final_state;
  float v_scale = (float)arg_scale;
  float v_lower_bound = (float)arg_lower_bound;
  void* kargs[] = {&p_q, &p_q_tma, &p_k, &p_k_tma, &p_v, &p_v_tma, &p_g, &p_g_tma, &p_beta, &p_beta_tma, &p_A_log, &p_dt_bias, &p_cu_seqlens, &p_seq_order, &p_initial_state, &p_out, &p_out_tma, &p_final_state, &v_state_indices_addr, &v_state_slot_stride, &v_use_state_indices, &p_initial_state_f32, &p_final_state_f32, &v_uniform_seq_len, &v_persistent_tasks, &v_persistent_stride, &v_num_heads, &v_use_initial_state, &v_store_final_state, &v_scale, &v_lower_bound};

  static std::mutex smem_mu;
  static auto* smem_status_by_device =
      new std::unordered_map<int, cudaError_t>();
  cudaError_t smem_status = cudaSuccess;
  {
    std::lock_guard<std::mutex> lock(smem_mu);
    auto it = smem_status_by_device->find(dev.device_id);
    if (it == smem_status_by_device->end()) {
      int current_device = -1;
      smem_status = cudaGetDevice(&current_device);
      if (smem_status == cudaSuccess && current_device != dev.device_id) {
        smem_status = cudaErrorInvalidDevice;
      }
      if (smem_status == cudaSuccess) {
        smem_status = cudaFuncSetAttribute(
            reinterpret_cast<const void*>(CAKE_KDA_SHARED_KERNEL),
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            226304);
      }
      smem_status_by_device->emplace(dev.device_id, smem_status);
    } else {
      smem_status = it->second;
    }
  }
  TVM_FFI_CHECK(smem_status == cudaSuccess, RuntimeError)
      << "cudaFuncSetAttribute for CAKE_KDA_SHARED_KERNEL failed: "
      << cudaGetErrorString(smem_status);
